param([string]$WorkspaceRoot,[string]$OutputPath)
$ErrorActionPreference='Stop';$candidate=Join-Path $WorkspaceRoot 'candidate.ps1';$rows=[Collections.Generic.List[object]]::new();$fixture=Join-Path ([IO.Path]::GetFullPath($WorkspaceRoot)) ('fixture-'+[guid]::NewGuid().ToString('N'));$null=New-Item -ItemType Directory $fixture;$entropy=[Text.Encoding]::UTF8.GetBytes('OutsideHarbor.SecretStore.v1')
function Invoke($a,$n,$v=''){$result=@(& $candidate -Action $a -StoreRoot $script:store -Name $n -Value $v);if($result.Count-ne 1){throw 'Single result required'};$result[0]}
function Snapshot($p){@(Get-ChildItem -LiteralPath $p -Recurse -File|Sort-Object FullName|ForEach-Object {($_.FullName.Substring($p.Length)+':'+(Get-FileHash -LiteralPath $_.FullName).Hash)})-join '|'}
function Case($id,$g,[scriptblock]$body){$script:store=Join-Path $fixture $id;$null=New-Item -ItemType Directory $script:store;$status='FAIL';$detail='';try{if((&$body)-eq $true){$status='PASS'}}catch{$detail=$_.Exception.Message};$rows.Add([pscustomobject]@{id=$id;group=$g;status=$status;detail=$detail})}
try{
 Case native_blob_roundtrip F2P {$secret="口令独立`n"+[guid]::NewGuid().ToString();$set=Invoke Set '名 [one]/x' $secret;$get=Invoke Get '名 [one]/x';$files=@(Get-ChildItem $store -File -Recurse);if($files.Count-ne 1){return $false};$blob=[IO.File]::ReadAllBytes($files[0].FullName);$scopeIsUser=($blob.Length -ge 44)-and(([BitConverter]::ToUInt32($blob,40)-band 4)-eq 0);$plain=[Security.Cryptography.ProtectedData]::Unprotect($blob,$entropy,[Security.Cryptography.DataProtectionScope]::CurrentUser);$wrongFailed=$false;try{$null=[Security.Cryptography.ProtectedData]::Unprotect($blob,$null,[Security.Cryptography.DataProtectionScope]::CurrentUser)}catch{$wrongFailed=$true};$set.Status-eq'stored'-and$get.Status-eq'found'-and$get.Value-ceq$secret-and[Text.Encoding]::UTF8.GetString($plain)-ceq$secret-and$scopeIsUser-and$wrongFailed-and-not([Text.Encoding]::UTF8.GetString($blob).Contains($secret))}
 Case case_name_isolation F2P {Invoke Set 'A' 'one'|Out-Null;Invoke Set 'a' 'two'|Out-Null;$other=Join-Path $fixture otherStore;$null=New-Item -ItemType Directory $other;$missing=@(&$candidate -Action Get -StoreRoot $other -Name 'A');(Invoke Get 'A').Value-ceq'one'-and(Invoke Get 'a').Value-ceq'two'-and$missing.Count-eq1-and$missing[0].Status-eq'missing'}
 Case overwrite_empty F2P {Invoke Set 'same' 'old'|Out-Null;Invoke Set 'same' ''|Out-Null;(Invoke Get 'same').Value-ceq''}
 Case remove_one F2P {Invoke Set 'x' '1'|Out-Null;Invoke Set 'y' '2'|Out-Null;(Invoke Remove 'x').Status-eq'removed'-and(Invoke Remove 'x').Status-eq'missing'-and(Invoke Get 'y').Value-ceq'2'}
 Case corrupt_preserved F2P {Invoke Set 'bad' 'valid'|Out-Null;$f=@(Get-ChildItem $store -File -Recurse)[0].FullName;[IO.File]::WriteAllBytes($f,[byte[]]@(1,2,3));$before=Snapshot $store;$r=Invoke Get 'bad';$r.Status-eq'corrupt'-and-not($r.PSObject.Properties.Name-contains'Value')-and$before-ceq(Snapshot $store)}
 Case missing_no_changes P2P {$before=Snapshot $store;(Invoke Get 'none').Status-eq'missing'-and(Invoke Remove 'none').Status-eq'missing'-and$before-ceq(Snapshot $store)}
 Case unrelated_and_boundary P2P {$keep=Join-Path $store 'keep.bin';[IO.File]::WriteAllBytes($keep,[byte[]]@(255,0,129));$before=Snapshot $fixture;Invoke Set '../outside/[name]' 'v'|Out-Null;Invoke Remove '../outside/[name]'|Out-Null;[Convert]::ToHexString([IO.File]::ReadAllBytes($keep))-ceq'FF0081'-and$before-ceq(Snapshot $fixture)}
}finally{if(Test-Path $fixture){Remove-Item $fixture -Recurse -Force}}
$manifest=Get-Content (Join-Path $PSScriptRoot 'rubric.json') -Raw|ConvertFrom-Json
$valid=$rows.Count-eq$manifest.required.Count
foreach($req in $manifest.required){$matches=@($rows|Where-Object{$_.id-ceq$req.id-and$_.group-ceq$req.group});if($matches.Count-ne1-or$matches[0].status-notin@('PASS','FAIL')){$valid=$false}}
$validity=if($valid){'VALID'}else{'INVALID'};$score=if($valid){[int](@($rows|Where-Object{$_.status-ne'PASS'}).Count-eq0)}else{$null}
$out=@{validity=$validity;score=$score;required=$manifest.required;testcases=$rows.ToArray();testcase_pass_count=@($rows|Where-Object{$_.status-eq'PASS'}).Count;testcase_total=$manifest.required.Count;fixture_cleaned=(-not(Test-Path $fixture))}
$null=New-Item -ItemType Directory -Path (Split-Path -Parent ([IO.Path]::GetFullPath($OutputPath))) -Force;$out|ConvertTo-Json -Depth 8|Set-Content $OutputPath -Encoding utf8;if(-not$valid){exit 2};if($score){exit 0};exit 1
